private fun quizQuestion(
    id: String,
    difficulty: BibleQuizDifficulty,
    prompt: String,
    options: List<String>,
    correct: Int,
    hardHint: String,
    easyHint: String,
    reference: String,
    explanation: String,
    book: String,
    chapter: Int,
    verse: Int? = null,
    endVerse: Int? = null
) = BibleQuizQuestion(
    id = id,
    prompt = prompt,
    options = options,
    correctOptionIndex = correct,
    difficulty = difficulty,
    hardHint = hardHint,
    easyHint = easyHint,
    bibleReference = reference,
    explanation = explanation,
    book = book,
    chapter = chapter,
    verse = verse,
    endVerse = endVerse
)

