        quizQuestion("hard_034", BibleQuizDifficulty.HARD, "De qual divisão sacerdotal Zacarias, pai de João Batista, fazia parte?", listOf("Abias", "Levi", "Zadoque", "Corá"), 0, "Lucas informa o grupo sacerdotal logo na apresentação de Zacarias.", "O nome é Abias.", "Lucas 1:5", "Zacarias pertencia à divisão sacerdotal de Abias.", "Lucas", 1, 5),
        quizQuestion("hard_035", BibleQuizDifficulty.HARD, "Segundo Mateus 1:17, em quantos grupos de quatorze gerações a genealogia é resumida?", listOf("2 grupos", "3 grupos", "4 grupos", "7 grupos"), 1, "O versículo divide a história de Abraão até Cristo em três períodos.", "São três conjuntos.", "Mateus 1:17", "Mateus resume a genealogia em três grupos de quatorze gerações.", "Mateus", 1, 17),
        quizQuestion("hard_036", BibleQuizDifficulty.HARD, "No Sermão do Monte, se alguém obrigasse uma pessoa a caminhar uma milha, quantas Jesus ensinou que ela deveria caminhar?", listOf("Uma", "Duas", "Três", "Sete"), 1, "O ensino vai além da exigência inicial.", "A resposta dobra a primeira distância.", "Mateus 5:41", "Jesus ensinou a ir duas milhas quando alguém obrigasse a caminhar uma.", "Mateus", 5, 41),
        quizQuestion("hard_037", BibleQuizDifficulty.HARD, "Qual dos dois discípulos no caminho de Emaús é identificado pelo nome?", listOf("Cléopas", "Bartimeu", "Nicodemos", "Matias"), 0, "Seu companheiro não é nomeado no texto.", "Seu nome começa com C.", "Lucas 24:13–18", "Lucas identifica um dos discípulos de Emaús como Cléopas.", "Lucas", 24, 13, 18),
        quizQuestion("hard_038", BibleQuizDifficulty.HARD, "Qual sumo sacerdote declarou que era conveniente que um homem morresse pelo povo?", listOf("Caifás", "Anás", "Zacarias", "Abiatar"), 0, "João comenta que ele profetizou sem compreender plenamente o alcance de suas palavras.", "Era sumo sacerdote naquele ano.", "João 11:49–52", "Caifás afirmou que seria conveniente um homem morrer pelo povo.", "João", 11, 49, 52),
        quizQuestion("hard_039", BibleQuizDifficulty.HARD, "Em qual ilha Paulo naufragou a caminho de Roma?", listOf("Creta", "Chipre", "Malta", "Patmos"), 2, "Os habitantes receberam os sobreviventes com hospitalidade.", "A ilha é nomeada logo no início de Atos 28.", "Atos 28:1–2", "Após o naufrágio, os sobreviventes descobriram que a ilha se chamava Malta.", "Atos", 28, 1, 2),
        quizQuestion("hard_040", BibleQuizDifficulty.HARD, "Em qual carta Paulo fala de Onésimo, a quem chama de filho gerado nas prisões?", listOf("Filemom", "Tito", "Gálatas", "Hebreus"), 0, "É uma carta curta dirigida ao senhor de Onésimo.", "O nome do destinatário é também o nome do livro.", "Filemom 1:10–16", "Paulo intercede por Onésimo na carta a Filemom.", "Filemom", 1, 10, 16)
    )

    init {
        require(questions.size == 120) { "O catálogo oficial precisa conter 120 perguntas." }
        BibleQuizDifficulty.entries.forEach { difficulty ->
            require(questions.count { it.difficulty == difficulty } == 40) {
                "Cada dificuldade precisa conter exatamente 40 perguntas."
            }
        }
        require(questions.map { it.id }.distinct().size == questions.size) { "IDs de perguntas não podem se repetir." }
        val invalid = questions.mapNotNull { question ->
            BibleQuizEngine.validate(question).takeIf { !it.valid }?.let { question.id to it.errors }
        }
        require(invalid.isEmpty()) {
            invalid.joinToString(separator = " | ") { (id, errors) -> "$id: ${errors.joinToString()}" }
        }
    }

    fun byDifficulty(difficulty: BibleQuizDifficulty): List<BibleQuizQuestion> =
        questions.filter { it.difficulty == difficulty }

    fun byId(id: String): BibleQuizQuestion? = questions.firstOrNull { it.id == id }
}
